["sex"] = 2,
},
["event"] = "CHAT_MSG_TEXT_EMOTE",
["type"] = "EMOTE",
},
["color"] = {
["r"] = 1,
["g"] = 0.501960813999176,
["b"] = 0.250980406999588,
},
["text"] = "You blush.",
["timestamp"] = 1776877883,
["id"] = "s17_3596",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: Catalogue every newcomer. I want no secrets among these latest arrivals.",
["timestamp"] = 1776877971,
["id"] = "s17_3597",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: I hunger for the opportunity to work together again. Come, let us forge a weapon worthy of your allies.",
["timestamp"] = 1776877979,
["id"] = "s17_3598",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: This is a delicate art. Your labor will imbue the blade with the energy of your very soul.",
["timestamp"] = 1776877990,
["id"] = "s17_3599",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: It will be an exquisite weapon for you. Now, follow my directions precisely.",
["timestamp"] = 1776877994,
["id"] = "s17_3600",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: Scatter behemoth bone dust over the Void-burning blade. It will harden the metal.",
["timestamp"] = 1776877997,
["id"] = "s17_3601",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: Yes, good. The energy you imbue in these components is crucial.",
["timestamp"] = 1776878001,
["id"] = "s17_3602",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: Use the crystalized Void to enhance the blade's edge!",
["timestamp"] = 1776878009,
["id"] = "s17_3603",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: Excellent.",
["timestamp"] = 1776878014,
["id"] = "s17_3604",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: Extract power from that Void repository. Quench it in shadow!",
["timestamp"] = 1776878021,
["id"] = "s17_3605",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_RAID_BOSS_WHISPER",
["type"] = "MONSTER_BOSS_WHISPER",
},
["color"] = {
["r"] = 1,
["g"] = 0.8666667342185974,
["b"] = 0,
},
["text"] = "The forging failed! We must start again!",
["timestamp"] = 1776878033,
["id"] = "s17_3606",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: Try again. You're better than this.",
["timestamp"] = 1776878033,
["id"] = "s17_3607",
},
{
["recordedBy"] = "Barelynoer-Area52",
["typeInfo"] = {
["player"] = {
["name"] = "Decimus",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Decimus says: Let me know when you want to try again.",
["timestamp"] = 1776878036,
["id"] = "s17_3608",
},
