edge]|h|rx1\",\"id\":\"s0_1887\",\"timestamp\":1772760151},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Solwin Brightstitch\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Solwin Brightstitch says: Alas, if I had but one worthy customer...\",\"id\":\"s0_1888\",\"timestamp\":1772760200},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Messenger Aelor\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Messenger Aelor says: Hello? Barelynoer? Can you hear me? I bring a message from Magister Umbric!\",\"id\":\"s0_1889\",\"timestamp\":1772760368},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Trading Post Barker\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Trading Post Barker says: Hey friend! Come check out our new items in the Trading Post. We just got a new shipment!\",\"id\":\"s0_1890\",\"timestamp\":1772760384},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"race\":\"Dracthyr\",\"class\":\"EVOKER\",\"name\":\"Barelynoer\",\"sex\":2},\"event\":\"CHAT_MSG_RAID_BOSS_EMOTE\",\"type\":\"MONSTER_BOSS_EMOTE\"},\"color\":{\"b\":0,\"g\":0.8666667342185974,\"r\":1},\"text\":\"A Darkmoon Ride Ticket has been consumed.\",\"id\":\"s0_1891\",\"timestamp\":1772760448},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Jay Maguire\"},\"event\":\"CHAT_MSG_MONSTER_YELL\",\"type\":\"MONSTER_YELL\"},\"color\":{\"b\":0.250980406999588,\"g\":0.250980406999588,\"r\":1},\"text\":\"Jay Maguire yells: One minute till Blight Boar takes the stage! Join us in the Cauldron of Rock on the east side of the island.\",\"id\":\"s0_1892\",\"timestamp\":1772760517},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Michael Schweitzer\"},\"event\":\"CHAT_MSG_MONSTER_YELL\",\"type\":\"MONSTER_YELL\"},\"color\":{\"b\":0.250980406999588,\"g\":0.250980406999588,\"r\":1},\"text\":\"Michael Schweitzer yells: The Tauren Chieftains concert will begin in thirty minutes!\",\"id\":\"s0_1893\",\"timestamp\":1772760571},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Jay Maguire\"},\"event\":\"CHAT_MSG_MONSTER_YELL\",\"type\":\"MONSTER_YELL\"},\"color\":{\"b\":0.250980406999588,\"g\":0.250980406999588,\"r\":1},\"text\":\"Jay Maguire yells: My rockin' and rollin' beauties! You're in the right place to melt your face! Allow me to humbly introduce... Blight Booooar!\",\"id\":\"s0_1894\",\"timestamp\":1772760582},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Death Metal Knight\"},\"event\":\"CHAT_MSG_MONSTER_YELL\",\"type\":\"MONSTER_YELL\"},\"color\":{\"b\":0.250980406999588,\"g\":0.250980406999588,\"r\":1},\"text\":\"Death Metal Knight yells: I will prove once and for all that only a knight from the grave can rule heavy metal.\",\"id\":\"s0_1895\",\"timestamp\":1772760590},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Death Metal Knight\"},\"event\":\"CHAT_MSG_MONSTER_YELL\",\"type\":\"MONSTER_YELL\"},\"color\":{\"b\":0.250980406999588,\"g\":0.250980406999588,\"r\":1},\"text\":\"Death Metal Knight yells: Fight though you might, your bodies will freeze and shatter!\",\"id\":\"s0_1896\",\"timestamp\":1772760613},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Death Metal Knight\"},\"event\":\"CHAT_MSG_MONSTER_YELL\",\"type\":\"MONSTER_YELL\"},\"color\":{\"b\":0.250980406999588,\"g\":0.250980406999588,\"r\":1},\"text\":\"Death Metal Knight yells: You have failed, Blight Boar.  Your fans now serve my armies of the dead!\",\"id\":\"s0_1897\",\"timestamp\":1772760666},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Charonus\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Charonus says: Do as you like, just make sure it's entertaining. Let the combat begin!\",\"id\":\"s0_1898\",\"timestamp\":1772760823},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"race\":\"Dracthyr\",\"class\":\"EVOKER\",\"name\":\"Kojapa-Kel'Thuzad\",\"sex\":2},\"event\":\"CHAT_MSG_GUILD\",\"type\":\"GUILD\"},\"color\":{\"b\":0.250980406999588,\"g\":1,\"r\":0.250980406999588},\"text\":\"|Hchannel:GUILD|h[Guild]|h |Hplayer:Kojapa-Kel'Thuzad:2563:GUILD:|h[|cff33937fKojapa|r]|h: wait you can rescue your aug duplicate\",\"id\":\"s0_1899\",\"timestamp\":1772760825},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"race\":\"Dracthyr\",\"class\":\"EVOKER\",\"name\":\"Kojapa-Kel'Thuzad\",\"sex\":2},\"event\":\"CHAT_MSG_GUILD\",\"type\":\"GUILD\"},\"color\":{\"b\":0.250980406999588,\"g\":1,\"r\":0.250980406999588},\"text\":\"|Hchannel:GUILD|h[Guild]|h |Hplayer:Kojapa-Kel'Thuzad:2564:GUILD:|h[|cff33937fKojapa|r]|h: that's massive tech\",\"id\":\"s0_1900\",\"timestamp\":1772760829},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"event\":\"CHAT_MSG_TARGETICONS\",\"type\":\"TARGETICONS\"},\"color\":{\"b\":0,\"g\":1,\"r\":1},\"text\":\"|Hplayer:Jeffzhangg|h[Jeffzhangg]|h sets |TInterface\\\\TargetingFrame\\\\UI-RaidTargetingIcon_6:0|t on Mîstîe.\",\"id\":\"s0_1901\",\"timestamp\":1772760843},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"race\":\"BloodElf\",\"class\":\"MONK\",\"name\":\"Mîstîe-Thrall\",\"sex\":3},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"b\":0,\"g\":0.6666666865348816,\"r\":0},\"text\":\"Mîstîe-Thrall receives loot: |cnIQ0:|Hitem:260659::::::::87:1473:::::::::|h[Stellar Vortex Residue]|h|r.\",\"id\":\"s0_1902\",\"timestamp\":1772760859},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"name\":\"Enthralled Shaman\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\"