s11_4011\"},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"|HlootHistory:3059|h[Loot]|h: Jugjuggies (Need - 86, Main-Spec) Won: |cnIQ2:|Hitem:256683::::::::90:1473::16::1:28:1279:::::|h[Silvermoon Training Dummy]|h|r\",\"timestamp\":1775236743,\"id\":\"s11_4012\"},{\"recordedBy\":\"Barelynoer-Area52\",\"typeInfo\":{\"player\":{\"class\":\"WARRIOR\",\"race\":\"Dwarf\",\"name\":\"Jugjuggies-Mal'Ganis\",\"sex\":2},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"Jugjuggies-Mal'Ganis receives loot: |cnIQ2:|Hitem:256683::::::::90:1473::16::1:28:1279:::::|h[Silvermoon Training Dummy]|h|r.\",\"timestamp\":1775236743,\"id\":\"s11_4013\"},{\"recordedBy\":\"Lonelylitten-Stormrage\",\"typeInfo\":{\"player\":{\"name\":\"Ranger Telenus\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Ranger Telenus says: Look at this mess!\",\"id\":\"s11_4014\",\"timestamp\":1775237129},{\"recordedBy\":\"Lonelylitten-Stormrage\",\"typeInfo\":{\"player\":{\"name\":\"Orweyna\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Orweyna says: The Den has been ravaged with vermin. If we deal with that problem the elders will be more favorable with us. Take a grymlinx--they are always up for a meal.\",\"id\":\"s11_4015\",\"timestamp\":1775237138},{\"recordedBy\":\"Lonelylitten-Stormrage\",\"typeInfo\":{\"event\":\"CHAT_MSG_CURRENCY\",\"type\":\"CURRENCY\"},\"color\":{\"b\":0,\"g\":0.6666666865348816,\"r\":0},\"text\":\"You receive currency: |cnIQ1:|Hcurrency:3316:0|h[Voidlight Marl]|h|rx1\",\"id\":\"s11_4016\",\"timestamp\":1775237185},{\"recordedBy\":\"Lonelylitten-Stormrage\",\"typeInfo\":{\"player\":{\"race\":\"NightElf\",\"class\":\"DRUID\",\"name\":\"Lonelylitten\",\"sex\":2},\"event\":\"CHAT_MSG_MONSTER_EMOTE\",\"type\":\"MONSTER_EMOTE\"},\"color\":{\"b\":0.250980406999588,\"g\":0.501960813999176,\"r\":1},\"text\":\"As you step inside, drawn ever closer to hidden treasure, your Coffer Key Shards stir as if awakened by the promise of riches. They shimmer, then fuse together, becoming whole once more.\",\"id\":\"s11_4017\",\"timestamp\":1775237190},{\"recordedBy\":\"Lonelylitten-Stormrage\",\"typeInfo\":{\"event\":\"CHAT_MSG_CURRENCY\",\"type\":\"CURRENCY\"},\"color\":{\"b\":0,\"g\":0.6666666865348816,\"r\":0},\"text\":\"You receive currency: |cnIQ4:|Hcurrency:3028:0|h[Restored Coffer Key]|h|rx3\",\"id\":\"s11_4018\",\"timestamp\":1775237191},{\"recordedBy\":\"Lonelylitten-Stormrage\",\"typeInfo\":{\"player\":{\"name\":\"Boletus\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Boletus says: Put on mask. You not Lonelylitten now. You evil Rotstalk!\",\"id\":\"s11_4019\",\"timestamp\":1775237199},{\"recordedBy\":\"Lonelylitten-Stormrage\",\"typeInfo\":{\"player\":{\"name\":\"Boletus\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Boletus says: Put on mask. You not Lonelylitten now. You evil Rotstalk!\",\"id\":\"s11_4020\",\"timestamp\":1775237201},{\"recordedBy\":\"Lonelylitten-Stormrage\",\"typeInfo\":{\"player\":{\"name\":\"Boletus\"},\"event\":\"CHAT_MSG_MONSTER_WHISPER\",\"type\":\"MONSTER_WHISPER\"},\"color\":{\"b\":0.9215686917304993,\"g\":0.7098039388656616,\"r\":1},\"text\":\"Boletus whispers: Remember, you evil. Make crowd mad.\",\"id\":\"s11_4021\",\"timestamp\":1775237201},{\"recordedBy\":\"Lonelylitten-Stormrage\",\"typeInfo\":{\"player\":{\"name\":\"Boletus\"},\"event\":\"CHAT_MSG_MONSTER_YELL\",\"type\":\"MONSTER_YELL\"},\"color\":{\"b\":0.250980406999588,\"g\":0.250980406999588,\"r\":1},\"text\":\"Boletus yells: Ahh, look out! Rotstalk come to fight.\",\"id\":\"s1